import{_ as p,a0 as o,w as d,s as h,ao as l,I as n,x as i,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Cron 任務入門指南 | LCTT x X-CMD","titleTemplate":false,"description":"Cron 任務入門指南 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cron 任務入門指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cron 任務入門指南 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180504 A Beginners Guide To Cron Jobs","title":"Cron 任務入門指南","tag":"201805","desc":""},"relativePath":"201805/20180504 A Beginners Guide To Cron Jobs.md","filePath":"[post].md"}'),g={name:"201805/20180504 A Beginners Guide To Cron Jobs.md"};function r(c,s,k,b,u,f){const e=o("Link");return d(),h("div",null,[s[18]||(s[18]=l(`<h1 id="cron-任務入門指南" tabindex="-1">Cron 任務入門指南 <a class="header-anchor" href="#cron-任務入門指南" aria-label="Permalink to “Cron 任務入門指南”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/cron-jobs1-720x340.jpg" alt=""></p><p><strong>Cron</strong> 是您可以在任何類 Unix 操作系統中找到的最有用的實用程序之一。它用於安排命令在特定時間執行。這些預定的命令或任務被稱為 “Cron 任務”。Cron 通常用於運行計劃備份、監視磁盤空間、定期刪除不再需要的文件（例如日誌文件）、運行系統維護任務等等。在本簡要指南中，我們將看到 Linux 中 Cron 任務的基本用法。</p><h3 id="cron-任務入門指南-1" tabindex="-1">Cron 任務入門指南 <a class="header-anchor" href="#cron-任務入門指南-1" aria-label="Permalink to “Cron 任務入門指南”">​</a></h3><p>cron 任務的典型格式是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>分鐘(0-59) 小時(0-24) 日(1-31) 月(1-12) 星期(0-6) 要執行的命令</span></span></code></pre></div><p>只需記住 cron 任務的格式或打印下面的插圖並將其放在你桌面上即可。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/cron-job-format-1.png" alt=""></p><p>在上圖中，星號表示特定的時間塊。</p><p>要顯示當前登錄用户的 crontab 文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -l</span></span></code></pre></div><p>要編輯當前用户的 cron 任務，請執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -e</span></span></code></pre></div><p>如果這是第一次編輯此文件，會詢問你使用哪個編輯器來編輯此文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>no crontab for sk - using an empty one</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Select an editor. To change later, run &#39;select-editor&#39;.</span></span>
<span class="line"><span>1. /bin/nano &lt;---- easiest</span></span>
<span class="line"><span>2. /usr/bin/vim.basic</span></span>
<span class="line"><span>3. /usr/bin/vim.tiny</span></span>
<span class="line"><span>4. /bin/ed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose 1-4 [1]:</span></span></code></pre></div><p>選擇適合你的編輯器。這裏是一個示例 crontab 文件的樣子。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/cron-jobs-1.png" alt=""></p><p>在這個文件中，你需要添加你的 cron 任務。</p><p>要編輯其他用户的 crontab，例如 ostechnix，請執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -u ostechnix -e</span></span></code></pre></div><p>讓我們看看一些例子。</p><p>要 <strong>每分鐘</strong> 執行一次 cron 任務，需使用如下格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>* * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>要每 5 分鐘運行一次 cron 任務，請在 crontab 文件中添加以下內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/5 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>要在每 1/4 個小時（每 15 分鐘）運行一次 cron 任務，請添加以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/15 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>要每小時的第 30 分鐘運行一次 cron 任務，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>30 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>您還可以使用逗號定義多個時間間隔。例如，以下 cron 任務每小時運行三次，分別在第 0、 5 和 10 分鐘運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0,5,10 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每半小時運行一次 cron 任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*/30 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每小時運行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 * * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每 2 小時運行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 */2 * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每天運行一項（在 00:00 運行）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每天凌晨 3 點運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 3 * * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每週日運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * SUN &lt;command-to-execute&gt;</span></span></code></pre></div><p>或使用，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * 0 &lt;command-to-execute&gt;</span></span></code></pre></div><p>它將在每週日的午夜 00:00 運行。</p><p>星期一至星期五每天運行一次，亦即每個工作日運行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 * * 1-5 &lt;command-to-execute&gt;</span></span></code></pre></div><p>這項工作將於 00:00 開始。</p><p>每個月運行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>於每月第 1 天的 16:15 運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15 16 1 * * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每季度運行一次，亦即每隔 3 個月的第 1 天運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 */3 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>在特定月份的特定時間運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>5 0 * 4 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>每個四月的 00:05 運行。</p><p>每 6 個月運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 */6 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>這個定時任務將在每六個月的第一天的 00:00 運行。</p><p>每年運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0 0 1 1 * &lt;command-to-execute&gt;</span></span></code></pre></div><p>這項 cron 任務將於 1 月份的第一天的 00:00 運行。</p><p>我們也可以使用以下字符串來定義任務。</p><p><code>@reboot</code> 在每次啓動時運行一次。 <code>@yearly</code> 每年運行一次。 <code>@annually</code>（和 <code>@yearly</code> 一樣）。 <code>@monthly</code> 每月運行一次。 <code>@weekly</code> 每週運行一次。 <code>@daily</code> 每天運行一次。 <code>@midnight</code> （和 <code>@daily</code> 一樣）。 <code>@hourly</code> 每小時運行一次。</p><p>例如，要在每次重新啓動服務器時運行任務，請將此行添加到您的 crontab 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@reboot &lt;command-to-execute&gt;</span></span></code></pre></div><p>要刪除當前用户的所有 cron 任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -r</span></span></code></pre></div>`,70)),n("p",null,[s[1]||(s[1]=i("還有一個名為 [crontab.guru] ",-1)),t(e,{href:"https://crontab.guru/"},{default:a(()=>[...s[0]||(s[0]=[i("4",-1)])]),_:1}),s[2]||(s[2]=i(" 的專業網站，用於學習 cron 任務示例。這個網站提供了很多 cron 任務的例子。",-1))]),s[19]||(s[19]=l('<p>有關更多詳細信息，請查看手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man crontab</span></span></code></pre></div><p>那麼，就是這樣。到此為止，您應該對 cron 任務以及如何在世使用它們有了一個基本的瞭解。後續還會介紹更多的優秀工具。敬請關注！！</p><p>乾杯!</p><hr>',5)),n("p",null,[s[4]||(s[4]=i("via: ",-1)),t(e,{href:"https://www.ostechnix.com/a-beginners-guide-to-cron-jobs/"},{default:a(()=>[...s[3]||(s[3]=[i("https://www.ostechnix.com/a-beginners-guide-to-cron-jobs/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=i("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[5]||(s[5]=[i("SK",-1)])]),_:1}),s[10]||(s[10]=i(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[6]||(s[6]=[i("lujun9972",-1)])]),_:1}),s[11]||(s[11]=i(" 譯者：",-1)),t(e,{href:"https://github.com/KevinSJ"},{default:a(()=>[...s[7]||(s[7]=[i("KevinSJ",-1)])]),_:1}),s[12]||(s[12]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[i("Linux中國",-1)])]),_:1}),s[17]||(s[17]=i(" 榮譽推出",-1))])])}const x=p(g,[["render",r]]);export{C as __pageData,x as default};
